var ENT=[["Router", "Signature Router pillar of the Email Service Integrator framework."], ["Guard", "Signature Guard pillar of the Email Service Integrator framework."], ["Issuer", "Signature Issuer pillar of the Email Service Integrator framework."], ["Limiter", "Signature Limiter pillar of the Email Service Integrator framework."], ["Validator", "Signature Validator pillar of the Email Service Integrator framework."], ["Queuer", "Signature Queuer pillar of the Email Service Integrator framework."], ["Watcher", "Signature Watcher pillar of the Email Service Integrator framework."]];
